sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 sourceColor;
layout(color) uniform half4 targetColor;
uniform float matchMode;
uniform float tolerance;
uniform float softness;
uniform float keepLuma;
uniform float invertMatch;
uniform float showMatte;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 sc = float3(sourceColor.rgb);
    float3 tc = float3(targetColor.rgb);
    float d = 0.0;
    if (matchMode < 0.5) {
        d = distance(s, sc) / 1.7320508;
    } else {
        float3 a = rgb2hsv(s);
        float3 b = rgb2hsv(sc);
        d = abs(fract(a.x - b.x + 0.5) - 0.5) * 2.0;
        d = mix(1.0, d, smoothstep(0.02, 0.2, a.y));
    }
    float w = 1.0 - smoothstep(tolerance * (1.0 - softness), tolerance + 0.0001, d);
    if (invertMatch > 0.5) w = 1.0 - w;
    float3 t = tc;
    if (keepLuma > 0.5) t = tc * (luma(s) / max(luma(sc), 0.1));
    float3 o = mix(s, t, w);
    if (showMatte > 0.5) o = float3(w);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
